  2	
  3	import com.loja.domain.entities.*;
  4	import com.loja.domain.events.PaymentConfirmedEvent;
  5	import com.loja.domain.observers.PaymentConfirmedObserver;
  6	import com.loja.domain.observers.StockObserver;
  7	import com.loja.repositories.CustomerRepository;
  8	import com.loja.repositories.NotificationRepository;
  9	import com.loja.repositories.OrderRepository;
 10	import com.loja.repositories.ProductRepository;
 11	import com.loja.repositories.impl.OrderRepositoryImpl;
 12	
 13	import java.time.Instant;
 14	import java.util.ArrayList;
 15	import java.util.List;
 16	import java.util.UUID;
 17	
 18	public class OrderService {
 19	    private final OrderRepository orderRepository;
 20	    private final CustomerRepository customerRepository;
 21	    private final NotificationRepository notificationRepository;
 22	    private final ProductRepository productRepository;
 23	    private final List<PaymentConfirmedObserver> paymentObservers;
 24	
 25	    public OrderService(
 26	            OrderRepository orderRepository,
 27	            CustomerRepository customerRepository,
 28	            NotificationRepository notificationRepository,
 29	            ProductRepository productRepository,
 30	            List<PaymentConfirmedObserver> paymentObservers) {
 31	        this.orderRepository = orderRepository;
 32	        this.customerRepository = customerRepository;
 33	        this.notificationRepository = notificationRepository;
 34	        this.productRepository = productRepository;
 35	        this.paymentObservers = paymentObservers;
 36	    }
 37	
 38	    public Order createOrder(String customerCpf, String customerEmail, List<OrderItem> items, OrderSummary summary) {
 39	        if (!customerRepository.exists(customerCpf)) {
 40	            Customer customer = new Customer(customerCpf);
 41	            customerRepository.save(customer);
 42	        }
 43	
 44	        String orderId = UUID.randomUUID().toString();
 45	        Order order = new Order(
 46	                orderId,
 47	                customerCpf,
 48	                customerEmail,
 49	                items,
 50	                summary,
 51	                OrderStatus.AWAITING_PAYMENT,
 52	                Instant.now()
 53	        );
 54	
 55	        orderRepository.save(order);
 56	        return order;
 57	    }
 58	
 59	    public Order confirmPayment(String orderId, String transactionId, Instant paidAt) throws PaymentException {
 60	        Order order = orderRepository.findById(orderId);
 61	        if (order == null) {
 62	            throw new PaymentException("Order not found");
 63	        }
 64	
 65	        if (orderRepository.hasPaymentTransaction(orderId, transactionId)) {
 66	            return order;
 67	        }
 68	
 69	        if (!order.canBePaid()) {
 70	            throw new PaymentException("Order cannot be paid in current status: " + order.getStatus());
 71	        }
 72	
 73	        if (order.isExpired(paidAt)) {
 74	            order.cancel();
 75	            orderRepository.update(order);
 76	            ((OrderRepositoryImpl) orderRepository).savePaymentTransaction(orderId, transactionId);
 77	
 78	            notifyCustomerCancellation(order);
 79	
 80	            throw new OrderExpiredException("Order expired");
 81	        }
 82	
 83	        try {
 84	            notifyPaymentConfirmed(order);
 85	
 86	            order.confirmPayment(transactionId, paidAt);
 87	            orderRepository.update(order);
 88	            ((OrderRepositoryImpl) orderRepository).savePaymentTransaction(orderId, transactionId);
 89	
 90	            return order;
 91	
 92	        } catch (StockObserver.InsufficientStockException e) {
 93	            order.cancel();
 94	            orderRepository.update(order);
 95	            ((OrderRepositoryImpl) orderRepository).savePaymentTransaction(orderId, transactionId);
 96	
 97	            notifyCustomerCancellation(order);
 98	
 99	            throw new InsufficientStockException("Insufficient stock");
100	        } catch (Exception e) {
101	            throw new PaymentException("Failed to confirm payment", e);
102	        }
103	    }
104	
105	    public Order shipOrder(String orderId, String trackingCode) throws ShipmentException {
106	        Order order = orderRepository.findById(orderId);
107	        if (order == null) {
108	            throw new ShipmentException("Order not found");
109	        }
110	
111	        if (!order.canBeShipped()) {
112	            throw new ShipmentException("Order cannot be shipped in current status: " + order.getStatus());
113	        }
114	
115	        order.ship(trackingCode);
116	        orderRepository.update(order);
117	
118	        notifyCustomerShipment(order);
119	
120	        return order;
121	    }
122	
123	    public Order deliverOrder(String orderId) throws DeliveryException {
124	        Order order = orderRepository.findById(orderId);
125	        if (order == null) {
126	            throw new DeliveryException("Order not found");
127	        }
128	
129	        if (!order.canBeDelivered()) {
130	            throw new DeliveryException("Order cannot be delivered in current status: " + order.getStatus());
131	        }
132	
133	        order.deliver();
134	        orderRepository.update(order);
135	
136	        return order;
137	    }
138	
139	    public Order cancelOrder(String orderId) throws CancellationException {
140	        Order order = orderRepository.findById(orderId);
141	        if (order == null) {
142	            throw new CancellationException("Order not found");
143	        }
144	
145	        if (!order.canBeCancelled()) {
146	            throw new CancellationException("Order cannot be cancelled in current status: " + order.getStatus());
147	        }
148	
149	        boolean wasPaid = order.getStatus() == OrderStatus.PAID;
150	
151	        order.cancel();
152	        orderRepository.update(order);
153	
154	        if (wasPaid) {
155	            reversePaymentEffects(order);
156	        }
157	
158	        notifyCustomerCancellation(order);
159	
160	        return order;
161	    }
162	
163	    private void notifyPaymentConfirmed(Order order) throws Exception {
164	        PaymentConfirmedEvent event = new PaymentConfirmedEvent(order);
165	
166	        for (PaymentConfirmedObserver observer : paymentObservers) {
167	            observer.onPaymentConfirmed(event);
168	        }
169	    }
170	
171	    private void reversePaymentEffects(Order order) {
172	        for (OrderItem item : order.getItems()) {
173	            Product product = productRepository.findBySku(item.getSku());
174	            product.increaseStock(item.getQuantity());
175	            productRepository.update(product);
176	        }
177	
178	        Money creditAmount = order.getSummary().getNextPurchaseCredit();
179	        if (creditAmount.isPositive()) {
180	            Customer customer = customerRepository.findByCpf(order.getCustomerCpf());
181	            customer.subtractCredit(creditAmount);
182	            customerRepository.update(customer);
183	        }
184	    }
185	
186	    private void notifyCustomerShipment(Order order) {
187	        Notification notification = new Notification(
188	                0,
189	                NotificationType.ORDER_SHIPPED,
190	                order.getId(),
191	                NotificationStatus.NEW
192	        );
193	        notificationRepository.save(order.getCustomerCpf(), notification);
194	    }
195	
196	    private void notifyCustomerCancellation(Order order) {
197	        Notification notification = new Notification(
198	                0,
199	                NotificationType.ORDER_CANCELLED,
200	                order.getId(),
201	                NotificationStatus.NEW
202	        );
203	        notificationRepository.save(order.getCustomerCpf(), notification);
204	    }
