206	    public static class PaymentException extends Exception {
207	        public PaymentException(String message) {
208	            super(message);
209	        }
210	
211	        public PaymentException(String message, Throwable cause) {
212	            super(message, cause);
213	        }
214	    }
215	
216	    public static class OrderExpiredException extends PaymentException {
217	        public OrderExpiredException(String message) {
218	            super(message);
219	        }
220	    }
221	
222	    public static class InsufficientStockException extends PaymentException {
223	        public InsufficientStockException(String message) {
224	            super(message);
225	        }
226	    }
227	
228	    public static class ShipmentException extends Exception {
229	        public ShipmentException(String message) {
230	            super(message);
231	        }
232	    }
233	
234	    public static class DeliveryException extends Exception {
235	        public DeliveryException(String message) {
236	            super(message);
237	        }
238	    }
239	
240	    public static class CancellationException extends Exception {
241	        public CancellationException(String message) {
242	            super(message);
243	        }
244	    }
245	}

